test("removeAllBut removes every blob not named and keeps the named, counting them") {
  fresh { blobs =>
    val _ = blobs.receive(bytes("keep"), 10)(_.keep())
    val _ = blobs.receive(bytes("drop"), 10)(_.keep())
    val named = Set(sha("keep"))
    (blobs.removeAllBut(named), blobs.at(sha("keep")).isDefined, blobs.at(sha("drop")),
      blobs.removeAllBut(named)) ==> (Right(1), true, None, Right(0))
  }
}
test("a removal failing partway leaves the blobs removed before it removed and the rest kept") {
  fresh { inner =>
    val _ = Vector("one", "two", "three").foreach(s => inner.receive(bytes(s), 10)(_.keep()))
    val named = Set(sha("three"))
    val stuck = sha("two")
    val flaky = new Blobs {
      def receive[A](in: InputStream^, max: Long)(body: Pending^ => A) =
        inner.receive(in, max)(body)
      def at(sha256: Sha256) = inner.at(sha256)
      def kept() = inner.kept().map(kept => Vector(sha("one"), stuck, sha("three")).filter(kept.contains))
      def remove(sha256: Sha256) =
        if (sha256 == stuck) Left(BlobError.Failed("stuck")) else inner.remove(sha256)
      def clearPending(before: Instant) = inner.clearPending(before)
    }
    (flaky.removeAllBut(named), inner.at(sha("one")).isEmpty, inner.at(stuck).isDefined,
      inner.at(sha("three")).isDefined) ==>
      (Left(BlobError.Failed("stuck")), true, true, true)
  }
}
