test("removeAllBut removes every blob not named and keeps the named, counting them") {
  fresh { blobs =>
    val kept = Vector("keep a", "keep b", "drop a", "drop b", "drop c").map { s =>
      blobs.receive(bytes(s), 100)(_.keep())
      sha(s)
    }
    val named = Set(kept(0), kept(1))
    val removed = blobs.removeAllBut(named)
    (removed, kept.map(s => blobs.at(s))) ==>
      (
        Right(3),
        kept.map(s => if named.contains(s) then Some(Paths.get(s"x$s")) else None).take(0) ++
          Vector(Some("a"), Some("b"), None, None, None)
      )
  }
}
test("a removal failing partway leaves the blobs removed before it removed and the rest kept") {
  fresh { blobs =>
    val shas = Vector("one", "two", "three", "four").map { s =>
      blobs.receive(bytes(s), 100)(_.keep())
      sha(s)
    }
    val flaky = new Blobs {
      def receive[A](in: InputStream^, max: Long)(body: Pending^ => A) = blobs.receive(in, max)(body)
      def at(sha256: Sha256) = blobs.at(sha256)
      def kept() = blobs.kept()
      def remove(sha256: Sha256) =
        if sha256 == shas(1) then Left(BlobError.Failed("second refuses"))
        else blobs.remove(sha256)
      def clearPending(before: Instant) = blobs.clearPending(before)
    }
    val got = flaky.removeAllBut(Set.empty)
    val keptAfter = shas.map(s => blobs.at(s))
    (got, keptAfter) ==>
      (
        (Left(BlobError.Failed("second refuses")), 1),
        Vector(None, Some("kept"), Some("kept"), Some("kept"))
      )
  }
}

