/** `body` over empty blobs, removed after. */
protected def fresh[A](body: Blobs^ => A): A

/** Everything `under` is, except its second `remove` fails. */
private final class Flaky(under: Blobs^, why: BlobError) extends Blobs {
  private var calls = 0
  def receive[A](in: InputStream^, max: Long)(body: Pending^ => A): Either[BlobError, A] =
    under.receive(in, max)(body)
  def at(sha256: Sha256): Option[Path] = under.at(sha256)
  def kept(): Either[BlobError, Vector[Sha256]] = under.kept()
  def remove(sha256: Sha256): Either[BlobError, Unit] = {
    calls += 1
    if calls == 2 then Left(why) else under.remove(sha256)
  }
  def clearPending(before: Instant): Either[BlobError, Int] = under.clearPending(before)
}

