def remove(sha256: Sha256): Either[BlobError, Unit]

/** Every blob not in `named` removed, how many, each named one kept; `Left` with the cause
  * when one removal fails, the blobs removed before it removed and the rest kept.
  */
def removeAllBut(named: Set[Sha256]): Either[BlobError, Int] = Right(0)

test("removeAllBut removes every blob not named and keeps the named, counting them") {
  fresh { blobs =>
    val _ = blobs.receive(bytes("gone one"), 20)(_.keep())
    val _ = blobs.receive(bytes("gone two"), 20)(_.keep())
    val _ = blobs.receive(bytes("kept"), 20)(_.keep())
    val keep = sha("kept")
    (blobs.removeAllBut(Set(keep)), blobs.kept()) ==>
      (Right(2), Right(Vector(keep)))
  }
}
test("a removal failing partway leaves the blobs removed before it removed and the rest kept") {
  fresh { base =>
    val _ = base.receive(bytes("one"), 20)(_.keep())
    val _ = base.receive(bytes("two"), 20)(_.keep())
    val _ = base.receive(bytes("three"), 20)(_.keep())
    val gone = base.kept().toOption.getOrElse(throw new java.lang.AssertionError("kept")).toVector
    val second = gone(1)
    val failing = new Blobs {
      def receive[A](in: InputStream^, max: Long)(body: Pending^ => A): Either[BlobError, A] =
        base.receive(in, max)(body)
      def at(sha256: Sha256): Option[Path] = base.at(sha256)
      def kept(): Either[BlobError, Vector[Sha256]] = base.kept()
      def remove(sha256: Sha256): Either[BlobError, Unit] =
        if (sha256 == second) Left(BlobError.Failed("second")) else base.remove(sha256)
      def clearPending(before: Instant): Either[BlobError, Int] = base.clearPending(before)
    }
    val left = gone.filterNot(_ == second)
    (failing.removeAllBut(Set.empty), base.kept().map(_.toSet)) ==>
      (Left(BlobError.Failed("second")), Right(left.toSet))
  }
}

